  int m = now.month;       // 1–12
  int d = now.day;         // 1–31
  int h = now.hour;        // 0–23
  int mi = now.minute;     // 0–59
  int s = now.second;      // 0–59
  int ms = now.millisecond;// 0–999

  // Compute total minutes since midnight.
  int totalMinutesSinceMidnight = (h * 60) + mi;

  // Calculate weeks elapsed this year from the start of January until today.
  // Start with days in previous months; add full weeks if enough days have passed.
  int weekCounter = 0;
  List<int> prevMonthDays = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30];
  bool isLeapYear = false;

  // Determine leap year status to adjust February's length correctly.
  if ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)) {
    isLeapYear = true;
  } else {
    isLeapYear = false;
  }

  // Add days accumulated up to the end of last month(s).
  for (int i = 0; i < m - 1; i++) {
    prevMonthDays[i] += isLeapYear ? 1 : 0;
    weekCounter += prevMonthDays[i].divRem(7).remainder;
  }

  // Add remaining days in the current month.
  weekCounter += (d - 1); // Subtract one because we don't count incomplete weeks yet.

  // Now compute how many complete weeks there are so far within this calendar year.
  weekCounter ~/= 7; // Integer division gives whole number of weeks.

  // Output all values as described.
  print('year=$y');
  print('month=$m');
  print('day=$d');
  print('hour=$h');
  print('minute=$mi');
  print('second=$s');
  print('millisecond=$ms');
  print('minutes-since-midnight=$totalMinutesSinceMidnight');
  print('weeks-passed-this-year-$weekCounter');
}

