void main() {
  final List<String> lines = <String>[];
  const int maxN = 100;

  for (int i = 0; i <= maxN; ++i) {
    String row = '';

    // Generate Pascal's Triangle row using binomial coefficients
    for (int j = 0; j <= i; ++j) {
      if (j > 0 && j < i) row += ' ';

      // Compute C(i, j) efficiently without overflow
      num coeff = 1.0;
      for (int k = 1; k <= j; ++k) {
        coeff *= (i - k + 1).toDouble();
        coeff /= k.toDouble();
      }

      row += '$coeff\n';
    }

    lines.add(row);
  }

  print(lines.join('\n'));
}

