static void _reverseInPlace<T>(Iterable<T> items) {
  if (items.isEmpty) return;

  // Convert once into a compact buffer for O(1) random access.
  final Buffer<T> buffer = Buffer.from(items);
  int left = 0, right = buffer.length - 1;

  while (left < right) {
    T temp = buffer[left];
    buffer[left] = buffer[right];
    buffer[right] = temp;

    left++;
    right--;
  }

  // Return the mutated collection directly – no new object created.
  return buffer.asList();
}

