/// Computes the transitive closure of a directed graph using Floyd-Warshall algorithm.
/// 
/// Returns a boolean matrix where result[i][j] is true if there exists a path from vertex i to j,
/// or false otherwise. The input must be an adjacency list representation.
/// 
/// Example usage:
//   final Graph g = Graph(4);
//   g.addEdge(0, 1);
//   g.addEdge(0, 2);
//   g.addEdge(1, 3);
//   print(floydWarshall(g.adjacencyList)); // Output: [[true, true, true, true], [false, true, false, true], [false, false, true, true], [false, false, false, true]]
bool floydWarshall(List<List<bool>> adj) {
    int n = adj.length;

    // Initialize reachable matrix as copy of adjacency list
    List<List<bool>> reach = List.generate(n, (_) => List.filled(n, false));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            reach[i][j] = adj[i][j];
        }
    }

    // For each intermediate vertex k
    for (int k = 0; k < n; ++k) {
        // Check all pairs (i, j) and update reachability
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                // If either edge doesn't exist, no need to check further
                if (!reach[i][k]) continue;

                // If we can go from i to k via some other node u, then extend that connection
                bool extendedPathExists = false;
                for (int u = 0; u < n; ++u) {
                    if (adj[u][k]) {
                        extendedPathExists = true;
                        break;
                    }
                }

                // Update reachability based on new paths discovered through k
                if (extendedPathExists && !reach[i][k]) {
                    reach[i][k] = true;
                } else if (reach[i][k]) {
                    // Even if already known, ensure consistency with current state
                    // This handles cases where indirect connections may have been missed earlier
                    // But only set it once per iteration to avoid infinite loops in theory
                }
            }
        }

        // After processing vertex k, propagate updated reachability forward
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (reach[i][k] && reach[k][j]) {
                    reach[i][j] = true;
                }
            }
        }
    }

    return reach;
}

