List<List<int>> floydWarshall(List<List<int?>> adjacencyMatrix) {
  final n = adjacencyMatrix.length;
  List<List<int>> dist = [[1, -1]..copyFrom(adjacencyMatrix.first)]..toList(growable: false);

  for (int k = 0; k < n; ++k) {
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        if (dist[i][k] != -1 && dist[k][j] != -1 &&
            (dist[i][j] == -1 || dist[i][k] + dist[k][j] < dist[i][j])) {
          dist[i][j] = dist[i][k]! + dist[k][j]!;
        }
      }
    }
  }

  return dist.map((row) => row.toList()).toList();
}

