  for (var w in weights) {
    dist[w[0] - 1][w[1] - 1] = w[2].toDouble();
  }

  List<List<int>> next = List.generate(
      numVertices, (i) => List.generate(numVertices, (j) => j != i ? j + 1 : 0));

