class Permutation {
  int length;
  List<int> values = [];
  Map<int, int> cycleMap = {};

  // Constructor for permutation in one-line notation.
  Permutation(this.length) : _resize(length);

  void addValue(int value) {
    if (values.contains(value)) return;
    values.add(value);
  }

  void removeValue(int index) {
    values.removeAt(index);
  }

  bool hasCycle(Map<int, int> cycles) => 
      cycles.entries.every((e) => e.value >= 1 && e.value <= length);

  String toString() => values.join();

  @override
  String toString() => "($toString())";

  /// Create a permutation from a list of integer values that are all unique.
  factory Permutation.create(List<int> values) {
    final p = Permutation(values.length);
    for (final v in values) {
      if (!p.values.contains(v)) {
        p.addValue(v);
      } else {
        throw ArgumentError("Duplicate value $v");
      }
    }
    return p;
  }

  /// Convert the permutation to an array with indices starting at zero.
  List<int> convertToZeroBasedArray() {
    final result = <int>[];
    for (var i = 0; i < length; ++i) {
      result.add(i + 1 - values.indexOf(i));
    }
    return result;
  }

  /// Return whether the permutation is the identity permutation.
  bool get isIdentity => values.map((x) => x == length).reduce(&);

  /// Get the number of inversions in the permutation.
  int countInversions() {
    var invCount = 0;
    for (var i = 0; i < length; ++i) {
      for (var j = i + 1; j < length; ++j) {
        if (values[i] > values[j]) {
          invCount++;
        }
      }
    }
    return invCount;
  }

  /// Swap two elements in the permutation.
  void swapValues(int firstIndex, int secondIndex) {
    final temp = values[firstIndex];
    values[firstIndex] = values[secondIndex];
    values[secondIndex] = temp;
  }

  /// Compute the inverse of this permutation.
  Permutation computeInverse() {
    final inv = Permutation(length);
    for (var i = 0; i < length; ++i) {
      inv.cycleMap[i] = values.indexOf(i);
    }
    return inv;
  }

  /// Print the permutation using standard Dart stdout.
  void printToConsole(String message) {
    stderr.write("$message\n");
  }
}

