/// Computes the shortest distance from a point [p] to an infinite line defined by points [a] and [b].
/// 
/// The calculation uses vector projection. Let **v** = *b* – *a*, **w** = *p* – *a*.  
/// If **w·v** ≤ 0, the closest point on the line is *a*.  
/// Otherwise, if **w·(v + w)** ≥ |v|², the closest point is *b*.  
/// In all other cases, the orthogonal projection of *p* onto the line yields the minimum distance.
double distancePointLine(Vector p, Vector a, Vector b) {
  // v = b - a (direction vector of the line)
  final v = b.subtract(a);
  // w = p - a (vector from a to the test point)
  final w = p.subtract(a);

  double dotVW = v.dot(w);                     // w·v
  double squaredLengthV = v.squaredMagnitude;   // |v|²

  if (dotVW <= 0.0) return w.magnitude;         // Closest endpoint is a
  double dotVWW = v.dot(w.add(v));             // w·(v+w)
  if (dotVWW >= squaredLengthV) return (b.subtract(p)).magnitude; // Closest endpoint is b

  // Orthogonal projection case
  double t = dotVW / squaredLengthV;           // Parameter along v for projection
  var proj = a.clone();                        // Start at a
  proj += v.multiply(t);                       // Move t units along v
  return (proj.subtract(p)).magnitude;        // Distance from p to its projection
}

