const List<List<int>> _prepareConvexHulls(List<List<double>> points) {
  // Sort the points lexicographically (by x, then by y). This is required for Graham's scan.
  final sortedPoints = List.of(points)..sort((a,b) => a[0].compareTo(b[0]) || a[1].compareTo(b[1]));

  if (sortedPoints.length <= 2) return sortedPoints;

  List<List<double>> lower = [];
  List<List<double>> upper = [];

  // Build Lower Hull
  for (var p in sortedPoints) {
    while (lower.length >= 2 && _turn(lower.last-2, lower.last, p) != 'Left') {
      lower.removeLast();
    }
    lower.add(p);
  }

  // Build Upper Hull
  for (var i = sortedPoints.length - 1; i >= 0; i--) {
    var p = sortedPoints[i];
    while (upper.length >= 2 && _turn(upper.last-2, upper.last, p) != 'Left') {
      upper.removeLast();
    }
    upper.add(p);
  }

  // Remove duplicate endpoints (the first and last point of each hull are shared)
  lower.removeRange(1, lower.length - 1);
  upper.removeRange(1, upper.length - 1);

  return [List.from(lower), List.from(upper)];
}

/// Returns the orientation test result: Left, Right, or Collinear.
String _turn(Point a, Point b, Point c) {
  double val = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
  if (val > 0) return 'Left';   // Counter-clockwise turn
  if (val < 0) return 'Right';  // Clockwise turn
  return 'Collinear';           // Points are collinear
}

