class ConvexHuldd {
  final Stack<Point2D> lower = [];
  final Stack<Point2D> upper = [];

  List<Point2D> compute(final Iterable<Point2D> pts) {
    if (pts.isEmpty) return [];

    for (final p in pts.sorted()) lower.push(p);

    while (lower.length >= 3 && _isRightTurn(lower[lower.length - 1], lower[lower.length - 2], lower[lower.length - 3])) {
      lower.pop();
    }

    for (int i = pts.length - 1; i >= 0; --i) {
      upper.push(pts[i]);
    }

    while (upper.length >= 3 && _isRightTurn(upper[upper.length - 1], upper[upper.length - 2], upper[upper.length - 3])) {
      upper.pop();
    }

    return [...lower, ...upper];
  }

  bool _isRightTurn(const Point2D a, const Point2D b, const Point2D c) {
    return (b.x - a.x) * (c.y - b.y) < (c.x - b.x) * (b.y - a.y);
  }
}

