void _generate(int depth, List<int> prefix, String alphabet, List<String> sequences) {
  if (depth == 0) {
    for (int i = 0; i < alphabet.length; i++) {
      int value = 2 * prefix[0] + i;
      if (!sequences.contains(value)) {
        sequences.add(value);
